8 |  *  - Emit the full ObserveReport as JSON to stdout when --json is requested.
9 |  *  - Exit with code 1 on any error; provide an actionable message to stderr.
10 |  *
11 |  * Redacts sensitive data (message content, tool arguments) before display.
12 |  * Demo mode loads fixtures/sample-export.json — no credentials, no network.
13 |  *
14 |  * The core pipeline (parseSession + observe) is pure and browser-safe.
15 |  * Only this file uses Node APIs (fs, path, process).
16 |  */
17 | 
18 | import { readFileSync } from "fs";
19 | import { join } from "path";
20 | import { parseSession } from "./parser/index";
21 | import { observe } from "./observe/index";
22 | import { toPublicReport } from "./observe/public-report";
23 | import { diagnoseWithCatalogs } from "./diagnose/index";
24 | import type { ObserveReport } from "./domain/types";
25 | 
26 | // ---------------------------------------------------------------------------
27 | // Helpers
28 | // ---------------------------------------------------------------------------
29 | 
30 | function die(message: string): never {
31 |   process.stderr.write(`\nHindsight error: ${message}\n\n`);
32 |   process.exit(1);
33 | }
34 | 
35 | function usage(): void {
36 |   process.stdout.write(
37 |     [
38 |       "",
39 |       "Hindsight — Phase 2 pipeline (parser + observe)",
40 |       "",
41 |       "Usage:",
42 |       "  npx tsx src/cli.ts --input <path/to/export.json> [--json]",
43 |       "  npx tsx src/cli.ts --demo [--json]",
44 |       "",
45 |       "Options:",
46 |       "  --input <file>   Path to the Bob session export JSON",
47 |       "  --demo           Run against fixtures/sample-export.json",
48 |       "  --json           Emit the full ObserveReport JSON to stdout",
49 |       "  --help           Show this help",
50 |       "",
51 |     ].join("\n")
52 |   );
53 | }
54 | 
55 | /** Parse CLI args — returns the input file path and flags. */
56 | function parseArgs(argv: string[]): { inputPath: string; emitJson: boolean } {
57 |   const args = argv.slice(2);
58 | 
59 |   if (args.includes("--help")) {
60 |     usage();
61 |     process.exit(0);
62 |   }
63 | 
64 |   let inputPath: string | null = null;
65 |   let emitJson = false;
66 | 
67 |   for (let i = 0; i < args.length; i++) {
68 |     if (args[i] === "--demo") {
69 |       inputPath = join(process.cwd(), "fixtures", "sample-export.json");
70 |     } else if (args[i] === "--input") {
71 |       const next = args[i + 1];
72 |       if (!next || next.startsWith("--")) {
73 |         die("--input requires a file path argument");
74 |       }
75 |       inputPath = next;
76 |       i++;
77 |     } else if (args[i] === "--json") {
78 |       emitJson = true;
79 |     }
80 |   }
81 | 
82 |   if (inputPath === null) {
83 |     die("No input file specified. Use --input <file> or --demo");
84 |   }
85 | 
86 |   return { inputPath, emitJson };
87 | }
88 | 
89 | // ---------------------------------------------------------------------------
90 | // Human-readable output
91 | // ---------------------------------------------------------------------------
92 | 
93 | /**
94 |  * Format the ObserveReport as a human-readable CLI summary.
95 |  * No sensitive fields (message content, tool arguments, task title, paths) are
96 |  * included in the output.
97 |  */
98 | function formatReport(report: ObserveReport): string {
99 |   const lines: string[] = [];
100 |   const diagnosis = diagnoseWithCatalogs(report);
101 | 
102 |   lines.push("");
103 |   lines.push("┌─ Hindsight — ObserveReport ──────────────────────────────────┐");
104 | 
105 |   // Session overview
106 |   lines.push("");
107 |   lines.push(`  Session     ${report.sessionId.slice(0, 12)}…`);
108 |   lines.push(`  Workspace   [REDACTED]`);
109 |   lines.push(`  Tasks       ${report.totals.taskCount} root  /  ${report.totals.subtaskCount} subtask(s)`);
110 | 
111 |   // Totals
112 |   lines.push("");
113 |   lines.push("  ── Totals (root tasks only) ──────────────────────────────────");
114 |   lines.push(`  Cost                 $${report.totals.cost.toFixed(6)}`);
115 |   lines.push(`  Assistant turns      ${report.totals.assistantTurns}`);
116 |   lines.push(`  Tool calls           ${report.totals.toolCalls}`);
117 |   lines.push(`  Errored tool calls   ${report.totals.erroredToolCalls}`);
118 |   lines.push(`  Human interventions  ${report.totals.humanInterventions}`);
119 |   lines.push(`  Diagnostic findings  ${diagnosis.findings.length}`);
120 | 
121 |   // Per-task detail
122 |   for (const task of report.tasks) {
123 |     const prefix = task.isSubtask ? "[subtask] " : "";
124 |     lines.push("");
125 |     lines.push(`  ── Task ${prefix}${task.taskId.slice(0, 12)}… ─────────────────────────────────`);
126 |     lines.push(`  Mode      ${task.modeId}`);
127 |     lines.push(`  Duration  ${(task.durationMs / 1000).toFixed(1)}s`);
128 |     lines.push(`  Completed ${task.completed ? "yes ✓" : "no"}`);
129 |     lines.push(`  Cost      $${task.cost.toFixed(6)}`);
130 |     lines.push("");
131 |     lines.push("  Context window:");
132 |     lines.push(`    Fixed overhead      ${task.context.fixedOverhead.toLocaleString()} tokens`);
133 |     lines.push(`    Conversation        ${task.context.conversationTokens.toLocaleString()} tokens`);
134 |     lines.push(`    Reported total      ${task.context.reportedTotal.toLocaleString()} tokens`);
135 |     if (task.context.pressure !== null) {
136 |       lines.push(`    Pressure            ${(task.context.pressure * 100).toFixed(1)}%`);
137 |     } else {
138 |       lines.push(`    Pressure            null  (no maxContextWindow configured)`);
139 |     }
140 |     lines.push("");
141 |     lines.push("  Tool inventory:");
142 |     if (task.toolInventory === null) {
143 |       lines.push(`    (unavailable — availableTools absent from export)`);
144 |     } else {
145 |       const inv = task.toolInventory;
146 |       const idleRatioPct = inv.idleRatio !== null ? `${(inv.idleRatio * 100).toFixed(1)}%` : "n/a";
147 |       lines.push(`    Available  ${inv.available.length}`);
148 |       lines.push(`    Used       ${inv.used.length}  (${inv.used.join(", ")})`);
149 |       lines.push(`    Idle       ${inv.idle.length}  (idle ratio: ${idleRatioPct})`);
150 |       lines.push(`    Tool defs  ${inv.toolDefinitionTokens} tokens`);
151 |       if (inv.estimatedTokensPerTool !== null) {
152 |         lines.push(`    Est. tokens/tool  ${inv.estimatedTokensPerTool} (estimate)`);
153 |       }
154 |     }
155 |     if (task.externalCommands.length > 0) {
156 |       lines.push("");
157 |       lines.push(`  External commands (${task.externalCommands.length}):`);
158 |       for (const cmd of task.externalCommands) {
159 |         lines.push(`    [turn ${cmd.turnIndex}] ${cmd.binaries.join(", ")}${cmd.isHttp ? "  [http]" : ""}`);
160 |       }
161 |     }
162 |     if (task.isSubtask) {
163 |       lines.push(`  (subtask — excluded from totals)`);
164 |     }
165 |   }
166 | 
167 |   // Unavailable metrics
168 |   lines.push("");
169 |   lines.push("  ── Unavailable metrics ───────────────────────────────────────");
170 |   lines.push(`  ${report.unavailableMetrics.join(", ")}`);
171 |   if (diagnosis.unavailableMetrics.length > 0) {
172 |     lines.push(`  ${diagnosis.unavailableMetrics.join(", ")}`);
173 |   }
174 | 
175 |   // Anomalies
176 |   if (report.anomalies.length > 0) {
177 |     lines.push("");
178 |     lines.push(`  ── Anomalies (${report.anomalies.length}) ──────────────────────────────────────`);
179 |     for (const a of report.anomalies) {
180 |       lines.push(`  [${a.kind}] ${a.detail}`);
181 |     }
182 |   }
183 | 
184 |   lines.push("");
185 |   lines.push("└──────────────────────────────────────────────────────────────┘");
186 |   lines.push("");
187 | 
188 |   return lines.join("\n");
189 | }
190 | 
191 | // ---------------------------------------------------------------------------
192 | // runObserve — pure orchestration (no Node APIs — testable without fs)
193 | // ---------------------------------------------------------------------------
194 | 
195 | /**
196 |  * Pure orchestration: takes raw export content (string) and returns
197 |  * { ok: true, report } or { ok: false, message }.
198 |  *
199 |  * No file system access. Browser-safe. Can be called identically in Node and
200 |  * browser (src/ui/).
201 |  */
202 | export function runObserve(
203 |   content: string,
204 |   maxContextWindow: number | null = null
205 | ): { ok: true; report: ObserveReport } | { ok: false; message: string } {
206 |   const parseResult = parseSession(content);
207 |   if (!parseResult.ok) {
208 |     return {
209 |       ok: false,
210 |       message: `Parse failed: ${parseResult.error.message}`,
211 |     };
212 |   }
213 |   const report = observe(parseResult.value, maxContextWindow);
214 |   return { ok: true, report };
215 | }
216 | 
217 | // ---------------------------------------------------------------------------
218 | // main — CLI entry point (Node only)
219 | // ---------------------------------------------------------------------------
220 | 
221 | function main(): void {
222 |   const { inputPath, emitJson } = parseArgs(process.argv);
223 | 
224 |   // Read file — the ONLY fs operation in the entire pipeline
225 |   let content: string;
226 |   try {
227 |     content = readFileSync(inputPath, "utf-8");
228 |   } catch (err) {
229 |     die(
230 |       `Cannot read file "${inputPath}": ${err instanceof Error ? err.message : String(err)}\n` +
231 |         `  Verify the path exists and is readable.`
232 |     );
233 |   }
234 | 
235 |   const result = runObserve(content);
236 |   if (!result.ok) {
237 |     die(result.message);
238 |   }
239 | 
240 |   const { report } = result;
241 | 
242 |   if (emitJson) {
243 |     // Emit a redacted projection — workspace, task titles, tool arguments,
244 |     // external command raw text, and human intervention content are replaced
245 |     // with [REDACTED] to prevent accidental leakage.
246 |     process.stdout.write(JSON.stringify(toPublicReport(report), null, 2) + "\n");
247 |   } else {
248 |     process.stdout.write(formatReport(report));
249 |   }
250 | }
251 | 
252 | // Only run as CLI entrypoint — not when imported as a module (tests, UI).
253 | // tsx sets import.meta.url; when run directly the url matches the argv[1] path.
254 | // Vitest imports this file as a module, so process.argv[1] will not be this file.
255 | if (
256 |   typeof process !== "undefined" &&
257 |   process.argv[1] !== undefined &&
258 |   (process.argv[1].endsWith("cli.ts") || process.argv[1].endsWith("cli.js"))
259 | ) {
260 |   main();
261 | }
262 |

