1 | /**
2 |  * Prescribe — AGENTS.md generator (F4 / #16)
3 |  *
4 |  * Transforms supported Findings into deterministic, reviewable AGENTS.md
5 |  * prescriptions. This module is pure and browser-safe: it performs no I/O,
6 |  * reads no raw export, and never consults the system clock.
7 |  *
8 |  * Allowed imports: src/domain/types.ts.
9 |  * Forbidden imports: parser, observe, compare, CLI/UI and Node APIs.
10 |  */
11 | 
12 | import type { EpochMs, Finding, Prescription } from "../domain/types";
13 | import { prescriptionId } from "./determinism";
14 | export { prescribeOverheadReduction } from "./overhead";
15 | 
16 | type AgentsMdFindingKind =
17 |   | "project-rules-absent"
18 |   | "human-intervention"
19 |   | "redundant-read"
20 |   | "retry-after-error";
21 | 
22 | type AgentsMdFinding = Omit<Finding, "kind"> & { kind: AgentsMdFindingKind };
23 | type SectionFinding = Omit<Finding, "kind"> & {
24 |   kind: Exclude<AgentsMdFindingKind, "project-rules-absent">;
25 | };
26 | 
27 | const KIND_ORDER: Readonly<Record<AgentsMdFindingKind, number>> = {
28 |   "project-rules-absent": 0,
29 |   "human-intervention": 1,
30 |   "redundant-read": 2,
31 |   "retry-after-error": 3,
32 | };
33 | 
34 | const BASE_RULE =
35 |   "- Keep repository-specific instructions concise, stable, and scoped to the current task.";
36 | 
37 | const SECTION_TEMPLATES: Readonly<
38 |   Partial<Record<AgentsMdFindingKind, { content: string; rationale: string }>>
39 | > = {
40 |   "human-intervention": {
41 |     content:
42 |       "- Confirm ambiguous requirements before making broad changes, and preserve decisions already established during the task.",
43 |     rationale:
44 |       "Reduces avoidable mid-task clarification without copying user message content.",
45 |   },
46 |   "redundant-read": {
47 |     content:
48 |       "- Reuse information already gathered during the task; reread a file only when it may have changed or its contents are no longer available.",
49 |     rationale:
50 |       "Reduces repeated reads without exposing the observed file path.",
51 |   },
52 |   "retry-after-error": {
53 |     content:
54 |       "- Inspect and address the cause of a failed operation before retrying it, then validate the result.",
55 |     rationale:
56 |       "Reduces blind retries without exposing commands, arguments, or raw errors.",
57 |   },
58 | };
59 | 
60 | function isAgentsMdFinding(finding: Finding): finding is AgentsMdFinding {
61 |   return Object.prototype.hasOwnProperty.call(KIND_ORDER, finding.kind);
62 | }
63 | 
64 | function compareFindings(a: AgentsMdFinding, b: AgentsMdFinding): number {
65 |   return (
66 |     KIND_ORDER[a.kind] - KIND_ORDER[b.kind] ||
67 |     a.sessionId.localeCompare(b.sessionId) ||
68 |     a.taskId.localeCompare(b.taskId) ||
69 |     a.detectedAt - b.detectedAt ||
70 |     a.id.localeCompare(b.id)
71 |   );
72 | }
73 | 
74 | function latestDetectedAt(findings: readonly Finding[]): EpochMs {
75 |   let latest = findings[0].detectedAt;
76 |   for (let index = 1; index < findings.length; index++) {
77 |     if (findings[index].detectedAt > latest) latest = findings[index].detectedAt;
78 |   }
79 |   return latest;
80 | }
81 | 
82 | function uniqueSupportedFindings(findings: readonly Finding[]): AgentsMdFinding[] {
83 |   const byId = new Map<string, AgentsMdFinding>();
84 | 
85 |   for (const finding of findings) {
86 |     if (!isAgentsMdFinding(finding) || byId.has(finding.id)) continue;
87 |     byId.set(finding.id, finding);
88 |   }
89 | 
90 |   return [...byId.values()].sort(compareFindings);
91 | }
92 | 
93 | function groupByTask(
94 |   findings: readonly AgentsMdFinding[]
95 | ): Array<readonly AgentsMdFinding[]> {
96 |   const groups = new Map<string, AgentsMdFinding[]>();
97 | 
98 |   for (const finding of findings) {
99 |     const key = `${finding.sessionId.length}:${finding.sessionId}${finding.taskId}`;
100 |     const group = groups.get(key);
101 |     if (group) group.push(finding);
102 |     else groups.set(key, [finding]);
103 |   }
104 | 
105 |   return [...groups.values()];
106 | }
107 | 
108 | function createSectionPrescription(
109 |   finding: SectionFinding
110 | ): Prescription {
111 |   const template = SECTION_TEMPLATES[finding.kind];
112 |   if (!template) {
113 |     // Exhaustive at runtime as well as at compile time; future kinds degrade safely.
114 |     throw new Error(`Missing safe AGENTS.md template for ${finding.kind}`);
115 |   }
116 | 
117 |   const findingIds = [finding.id];
118 |   return {
119 |     id: prescriptionId("agents-md-section", finding.sessionId, finding.taskId, findingIds),
120 |     sessionId: finding.sessionId,
121 |     taskId: finding.taskId,
122 |     findingIds,
123 |     kind: "agents-md-section",
124 |     status: "pending",
125 |     createdAt: finding.detectedAt,
126 |     content: template.content,
127 |     rationale: template.rationale,
128 |   };
129 | }
130 | 
131 | function renderSectionContents(sections: readonly Prescription[]): string {
132 |   const seen = new Set<string>();
133 |   const rules: string[] = [BASE_RULE];
134 | 
135 |   for (const section of sections) {
136 |     if (section.kind !== "agents-md-section" || !section.content || seen.has(section.content)) {
137 |       continue;
138 |     }
139 |     seen.add(section.content);
140 |     rules.push(section.content);
141 |   }
142 | 
143 |   return `# AGENTS.md\n\n## Working guidelines\n\n${rules.join("\n")}`;
144 | }
145 | 
146 | /**
147 |  * Generate only the AGENTS.md prescription family from Finding[].
148 |  *
149 |  * Sensitive Finding fields are deliberately never read while producing content:
150 |  * description, prescription, evidence, metrics and Finding IDs remain audit
151 |  * metadata and cannot flow into the generated Markdown.
152 |  */
153 | export function prescribeAgentsMd(findings: readonly Finding[]): Prescription[] {
154 |   const supported = uniqueSupportedFindings(findings);
155 |   if (supported.length === 0) return [];
156 | 
157 |   const result: Prescription[] = [];
158 | 
159 |   for (const group of groupByTask(supported)) {
160 |     const sections = group
161 |       .filter(
162 |         (finding): finding is SectionFinding => finding.kind !== "project-rules-absent"
163 |       )
164 |       .map(createSectionPrescription);
165 | 
166 |     result.push(...sections);
167 | 
168 |     const findingIds = group.map((finding) => finding.id);
169 |     const first = group[0];
170 |     result.push({
171 |       id: prescriptionId("agents-md-file", first.sessionId, first.taskId, findingIds),
172 |       sessionId: first.sessionId,
173 |       taskId: first.taskId,
174 |       findingIds,
175 |       kind: "agents-md-file",
176 |       status: "pending",
177 |       createdAt: latestDetectedAt(group),
178 |       content: renderSectionContents(sections),
179 |       targetFile: "AGENTS.md",
180 |       rationale:
181 |         "Provides a minimal, reviewable project-instruction draft derived from supported findings.",
182 |     });
183 |   }
184 | 
185 |   return result;
186 | }
187 | 
188 | /**
189 |  * Render AGENTS.md content from prescriptions produced by prescribeAgentsMd().
190 |  * File prescriptions take precedence because they already contain the composed
191 |  * draft. With section-only input, a minimal document is composed deterministically.
192 |  */
193 | export function renderAgentsMd(prescriptions: readonly Prescription[]): string {
194 |   const files = prescriptions
195 |     .filter(
196 |       (prescription): prescription is Prescription & { content: string } =>
197 |         prescription.kind === "agents-md-file" && typeof prescription.content === "string"
198 |     )
199 |     .sort(
200 |       (a, b) =>
201 |         a.sessionId.localeCompare(b.sessionId) ||
202 |         a.taskId.localeCompare(b.taskId) ||
203 |         a.id.localeCompare(b.id)
204 |     );
205 | 
206 |   if (files.length > 0) return files.map((file) => file.content).join("\n\n---\n\n");
207 | 
208 |   const sections = prescriptions
209 |     .filter((prescription) => prescription.kind === "agents-md-section")
210 |     .sort(
211 |       (a, b) =>
212 |         a.sessionId.localeCompare(b.sessionId) ||
213 |         a.taskId.localeCompare(b.taskId) ||
214 |         a.createdAt - b.createdAt ||
215 |         a.id.localeCompare(b.id)
216 |     );
217 | 
218 |   return sections.length > 0 ? renderSectionContents(sections) : "";
219 | }
