1 | /**
2 |  * F4 / #17 — deterministic tool-reduction and Skill-overhead prescriptions.
3 |  *
4 |  * Consumes Findings already enriched by Diagnose. It deliberately does not
5 |  * import or reload recommendation catalogues.
6 |  */
7 | 
8 | import type { Finding, Prescription } from "../domain/types";
9 | import { prescriptionId } from "./determinism";
10 | 
11 | interface IdleToolMetric {
12 |   name: string;
13 |   group: string;
14 |   purpose: string | null;
15 |   essential: boolean;
16 | }
17 | 
18 | interface ParsedUnusedToolFinding {
19 |   finding: Finding;
20 |   candidates: IdleToolMetric[];
21 |   retainedEssential: IdleToolMetric[];
22 |   tokenImpact: number | undefined;
23 | }
24 | 
25 | interface ParsedSkillFinding {
26 |   finding: Finding;
27 |   tokenImpact: number | undefined;
28 | }
29 | 
30 | function isRecord(value: unknown): value is Record<string, unknown> {
31 |   return typeof value === "object" && value !== null && !Array.isArray(value);
32 | }
33 | 
34 | function isFiniteNonNegative(value: unknown): value is number {
35 |   return typeof value === "number" && Number.isFinite(value) && value >= 0;
36 | }
37 | 
38 | function isFinitePositive(value: unknown): value is number {
39 |   return typeof value === "number" && Number.isFinite(value) && value > 0;
40 | }
41 | 
42 | function isNonEmptyString(value: unknown): value is string {
43 |   return typeof value === "string" && value.length > 0;
44 | }
45 | 
46 | function parseIdleTool(value: unknown): IdleToolMetric | null {
47 |   if (!isRecord(value)) return null;
48 |   if (
49 |     !isNonEmptyString(value.name) ||
50 |     !isNonEmptyString(value.group) ||
51 |     !(value.purpose === null || isNonEmptyString(value.purpose)) ||
52 |     typeof value.essential !== "boolean"
53 |   ) {
54 |     return null;
55 |   }
56 | 
57 |   return {
58 |     name: value.name,
59 |     group: value.group,
60 |     purpose: value.purpose,
61 |     essential: value.essential,
62 |   };
63 | }
64 | 
65 | function sortedUniqueStrings(values: readonly string[]): string[] {
66 |   return [...new Set(values)].sort((a, b) => a.localeCompare(b));
67 | }
68 | 
69 | function equalStrings(a: readonly string[], b: readonly string[]): boolean {
70 |   return a.length === b.length && a.every((value, index) => value === b[index]);
71 | }
72 | 
73 | function parseUnusedToolFinding(finding: Finding): ParsedUnusedToolFinding | null {
74 |   if (
75 |     finding.kind !== "unused-tool" ||
76 |     finding.evidence.redactable ||
77 |     !Array.isArray(finding.evidence.unusedTools) ||
78 |     finding.evidence.unusedTools.length === 0 ||
79 |     !finding.evidence.unusedTools.every(isNonEmptyString)
80 |   ) {
81 |     return null;
82 |   }
83 | 
84 |   const rawIdleTools = finding.metric.idleTools;
85 |   const candidateCount = finding.metric.disableCandidateCount;
86 |   if (
87 |     !Array.isArray(rawIdleTools) ||
88 |     rawIdleTools.length === 0 ||
89 |     !Number.isInteger(candidateCount) ||
90 |     !isFiniteNonNegative(candidateCount) ||
91 |     finding.metric.tokenImpactIsEstimate !== true
92 |   ) {
93 |     return null;
94 |   }
95 | 
96 |   const byName = new Map<string, IdleToolMetric>();
97 |   for (const rawTool of rawIdleTools) {
98 |     const tool = parseIdleTool(rawTool);
99 |     if (!tool) return null;
100 |     const existing = byName.get(tool.name);
101 |     if (existing) {
102 |       if (
103 |         existing.group !== tool.group ||
104 |         existing.purpose !== tool.purpose ||
105 |         existing.essential !== tool.essential
106 |       ) {
107 |         return null;
108 |       }
109 |       continue;
110 |     }
111 |     byName.set(tool.name, tool);
112 |   }
113 | 
114 |   const tools = [...byName.values()].sort((a, b) => a.name.localeCompare(b.name));
115 |   const candidates = tools.filter((tool) => !tool.essential);
116 |   const retainedEssential = tools.filter((tool) => tool.essential);
117 |   const evidenceCandidates = sortedUniqueStrings(finding.evidence.unusedTools);
118 |   const metricCandidates = candidates.map((tool) => tool.name);
119 | 
120 |   if (
121 |     candidateCount !== candidates.length ||
122 |     !equalStrings(evidenceCandidates, metricCandidates)
123 |   ) {
124 |     return null;
125 |   }
126 | 
127 |   if (finding.tokenImpact !== undefined && !isFiniteNonNegative(finding.tokenImpact)) {
128 |     return null;
129 |   }
130 | 
131 |   return {
132 |     finding,
133 |     candidates,
134 |     retainedEssential,
135 |     tokenImpact: finding.tokenImpact,
136 |   };
137 | }
138 | 
139 | function parseSkillFinding(finding: Finding): ParsedSkillFinding | null {
140 |   if (finding.kind !== "skill-overhead" || finding.evidence.redactable) return null;
141 | 
142 |   const skillTokens = finding.metric.skillTokens;
143 |   const loadedSkills = finding.metric.loadedSkills;
144 |   if (!isFinitePositive(skillTokens)) return null;
145 |   if (
146 |     loadedSkills !== undefined &&
147 |     (!Array.isArray(loadedSkills) || !loadedSkills.every(isNonEmptyString) || loadedSkills.length > 0)
148 |   ) {
149 |     return null;
150 |   }
151 |   if (finding.tokenImpact !== undefined && !isFinitePositive(finding.tokenImpact)) {
152 |     return null;
153 |   }
154 | 
155 |   return { finding, tokenImpact: finding.tokenImpact };
156 | }
157 | 
158 | function retainedRationale(retained: readonly IdleToolMetric[]): string {
159 |   if (retained.length === 0) return "";
160 |   return ` Catalogue-protected essential tools retained: ${retained
161 |     .map((tool) => tool.name)
162 |     .join(", ")}.`;
163 | }
164 | 
165 | function toolPrescriptions(parsed: ParsedUnusedToolFinding): Prescription[] {
166 |   if (parsed.candidates.length === 0) return [];
167 | 
168 |   const groups = new Map<string, IdleToolMetric[]>();
169 |   for (const tool of parsed.candidates) {
170 |     const group = groups.get(tool.group);
171 |     if (group) group.push(tool);
172 |     else groups.set(tool.group, [tool]);
173 |   }
174 | 
175 |   const orderedGroups = [...groups.entries()].sort(([a], [b]) => a.localeCompare(b));
176 |   const findingIds = [parsed.finding.id];
177 |   const estimatedPerCandidate =
178 |     parsed.tokenImpact === undefined
179 |       ? undefined
180 |       : parsed.tokenImpact / parsed.candidates.length;
181 |   let allocatedSaving = 0;
182 | 
183 |   return orderedGroups.map(([group, tools], index) => {
184 |     tools.sort((a, b) => a.name.localeCompare(b.name));
185 |     let estimatedTokenSaving: number | undefined;
186 |     if (estimatedPerCandidate !== undefined && parsed.tokenImpact !== undefined) {
187 |       estimatedTokenSaving =
188 |         index === orderedGroups.length - 1
189 |           ? parsed.tokenImpact - allocatedSaving
190 |           : estimatedPerCandidate * tools.length;
191 |       allocatedSaving += estimatedTokenSaving;
192 |     }
193 | 
194 |     const toolList = tools.map((tool) => `- ${tool.name}`).join("\n");
195 |     return {
196 |       id: prescriptionId(
197 |         "disable-tool",
198 |         parsed.finding.sessionId,
199 |         parsed.finding.taskId,
200 |         findingIds,
201 |         group
202 |       ),
203 |       sessionId: parsed.finding.sessionId,
204 |       taskId: parsed.finding.taskId,
205 |       findingIds,
206 |       kind: "disable-tool",
207 |       status: "pending",
208 |       createdAt: parsed.finding.detectedAt,
209 |       content:
210 |         `Group: ${group}\n\n` +
211 |         "Estimated recommendation for this analyzed session:\n\n" +
212 |         toolList,
213 |       rationale:
214 |         "These tools were available but unused in the analyzed session. " +
215 |         "Review their necessity in other workflows before disabling them. " +
216 |         "Potential token savings are estimated, not individually measured." +
217 |         retainedRationale(parsed.retainedEssential),
218 |       ...(estimatedTokenSaving === undefined ? {} : { estimatedTokenSaving }),
219 |     };
220 |   });
221 | }
222 | 
223 | function skillPrescription(parsed: ParsedSkillFinding): Prescription {
224 |   const findingIds = [parsed.finding.id];
225 |   return {
226 |     id: prescriptionId(
227 |       "disable-skill",
228 |       parsed.finding.sessionId,
229 |       parsed.finding.taskId,
230 |       findingIds
231 |     ),
232 |     sessionId: parsed.finding.sessionId,
233 |     taskId: parsed.finding.taskId,
234 |     findingIds,
235 |     kind: "disable-skill",
236 |     status: "pending",
237 |     createdAt: parsed.finding.detectedAt,
238 |     content:
239 |       "Review global or installed Skills enabled for this workflow. " +
240 |       "The export reports aggregate Skill overhead but does not identify a specific Skill target.",
241 |     rationale:
242 |       "Estimated aggregate Skill overhead for the analyzed session; no concrete Skill was identified.",
243 |     ...(parsed.tokenImpact === undefined
244 |       ? {}
245 |       : { estimatedTokenSaving: parsed.tokenImpact }),
246 |   };
247 | }
248 | 
249 | /** Generate deterministic tool and Skill overhead prescriptions from enriched Findings. */
250 | export function prescribeOverheadReduction(
251 |   findings: readonly Finding[]
252 | ): Prescription[] {
253 |   const unique = new Map<string, Finding>();
254 |   for (const finding of findings) {
255 |     if (
256 |       (finding.kind === "unused-tool" || finding.kind === "skill-overhead") &&
257 |       !unique.has(finding.id)
258 |     ) {
259 |       unique.set(finding.id, finding);
260 |     }
261 |   }
262 | 
263 |   const ordered = [...unique.values()].sort(
264 |     (a, b) =>
265 |       a.sessionId.localeCompare(b.sessionId) ||
266 |       a.taskId.localeCompare(b.taskId) ||
267 |       a.kind.localeCompare(b.kind) ||
268 |       a.detectedAt - b.detectedAt ||
269 |       a.id.localeCompare(b.id)
270 |   );
271 | 
272 |   const result: Prescription[] = [];
273 |   for (const finding of ordered) {
274 |     const unused = parseUnusedToolFinding(finding);
275 |     if (unused) {
276 |       result.push(...toolPrescriptions(unused));
277 |       continue;
278 |     }
279 |     const skill = parseSkillFinding(finding);
280 |     if (skill) result.push(skillPrescription(skill));
281 |   }
282 |   return result;
283 | }
